{
  "title": "functions.expression.ObjectInputSchema",
  "description": "Schema for an object input with named properties.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the object.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "properties": {
      "description": "Schema for each property in the object.",
      "type": "object",
      "additionalProperties": {
        "$ref": "functions.expression.InputSchema"
      }
    },
    "required": {
      "description": "List of property names that must be present.",
      "anyOf": [
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.ObjectInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.ArrayInputSchema",
  "description": "Schema for an array input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the array.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "items": {
      "description": "Schema for each item in the array.",
      "$ref": "functions.expression.InputSchema"
    },
    "maxItems": {
      "description": "Maximum number of items allowed.",
      "anyOf": [
        {
          "type": "integer",
          "minimum": 0,
          "maximum": 18446744073709551615
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "minItems": {
      "description": "Minimum number of items required.",
      "anyOf": [
        {
          "type": "integer",
          "minimum": 0,
          "maximum": 18446744073709551615
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.ArrayInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.StringInputSchema",
  "description": "Schema for a string input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the string.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "enum": {
      "description": "If provided, the string must be one of these values.",
      "anyOf": [
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.StringInputSchemaType"
    }
  }
}

{
  "title": "agent.completions.message.VideoUrl",
  "description": "A video URL for multimodal input.",
  "type": "object",
  "properties": {
    "url": {
      "description": "The URL of the video.",
      "type": "string"
    }
  }
}

{
  "title": "agent.completions.message.RichContentPart",
  "description": "A part of rich content.",
  "anyOf": [
    {
      "title": "Text",
      "description": "Text content.",
      "type": "object",
      "properties": {
        "text": {
          "type": "string"
        },
        "type": {
          "type": "string",
          "enum": [
            "text"
          ]
        }
      }
    },
    {
      "title": "ImageUrl",
      "description": "An image URL.",
      "type": "object",
      "properties": {
        "image_url": {
          "$ref": "agent.completions.message.ImageUrl"
        },
        "type": {
          "type": "string",
          "enum": [
            "image_url"
          ]
        }
      }
    },
    {
      "title": "InputAudio",
      "description": "Audio input.",
      "type": "object",
      "properties": {
        "input_audio": {
          "$ref": "agent.completions.message.InputAudio"
        },
        "type": {
          "type": "string",
          "enum": [
            "input_audio"
          ]
        }
      }
    },
    {
      "title": "InputVideo",
      "description": "Video input.",
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "enum": [
            "input_video"
          ]
        },
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        }
      }
    },
    {
      "title": "VideoUrl",
      "description": "A video URL.",
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "enum": [
            "video_url"
          ]
        },
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        }
      }
    },
    {
      "title": "File",
      "description": "A file.",
      "type": "object",
      "properties": {
        "file": {
          "$ref": "agent.completions.message.File"
        },
        "type": {
          "type": "string",
          "enum": [
            "file"
          ]
        }
      }
    }
  ]
}

{
  "title": "functions.expression.Expression",
  "description": "An expression that can be either JMESPath or Starlark.\n\nSerializes as `{\"$jmespath\": \"...\"}` or `{\"$starlark\": \"...\"}` in JSON.\n\n# Examples\n\nJMESPath:\n```json\n{\"$jmespath\": \"input.items[0].name\"}\n```\n\nStarlark:\n```json\n{\"$starlark\": \"input['items'][0]['name']\"}\n```",
  "anyOf": [
    {
      "title": "JMESPath",
      "description": "A JMESPath expression.",
      "type": "object",
      "properties": {
        "$jmespath": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    {
      "title": "Starlark",
      "description": "A Starlark expression.",
      "type": "object",
      "properties": {
        "$starlark": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    {
      "title": "Special",
      "description": "A predefined special expression variant.",
      "type": "object",
      "properties": {
        "$special": {
          "$ref": "functions.expression.Special"
        }
      },
      "additionalProperties": false
    }
  ]
}

{
  "title": "functions.expression.VideoInputSchema",
  "description": "Schema for a video input (URL or base64-encoded).",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected video.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.VideoInputSchemaType"
    }
  }
}
